/// <summary>
/// PricingAttribute of table <c>CFMDirPartyTable</c> field PaymentPriority.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCFMDirPartyTablePaymentPriority extends UPSPricingAttributeCFMDirPartyTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CFMDirPartyTable, PaymentPriority);
}

public Set getAllowedValues()
{
    var              ret = new Set(Types::String);
    CFMDirPartyTable cFMDirPartyTable;

    while select cFMDirPartyTable
        group by PaymentPriority
    {
        if (! ret.in(cFMDirPartyTable.PaymentPriority))
        {
            ret.add(cFMDirPartyTable.PaymentPriority);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CFMDirPartyTable, PaymentPriority));
    qbr.value(queryValue(_value));
}
